return {["modules/era/lua/actions/spells/spell_adjustments.lua"]={["Path"]="modules/era/lua/actions/spells/spell_adjustments.lua",["SHA256"]="d8364b1e912483437bb7d789d4433d247d794ea0f1331ff4b87ad154ad14f39a",["Text"]="-----------------------------------\n-- Module: Spell Adjustments (Rhapsodies of Vana'diel Era)\n-- Desc: Reverts spell changes introduced during the RoV era\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('rov_spell_adjustments', xi.pre(xi.expansion.ROV))\n\n-----------------------------------\n-- Enfeebling Magic\n-----------------------------------\n\n-- Dia family: Revert defense down values.\n-- Source: https://forum.square-enix.com/ffxi/threads/55263-April.-3-2019-%28JST%29-Version-Update\nlocal function castEraDia(caster, target, spell, tier, dotPower, duration, defenseDown)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n\n    -- Check for Bio.\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = dotPower + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = duration, origin = caster, tick = 3, subPower = defenseDown, tier = tier })\n    end\n\n    return damage\nend\n\nm:addOverride('xi.actions.spells.white.dia.onSpellCast', function(caster, target, spell)\n    return castEraDia(caster, target, spell, 1, 1, 60, 5)\nend)\n\nm:addOverride('xi.actions.spells.white.dia_ii.onSpellCast', function(caster, target, spell)\n    return castEraDia(caster, target, spell, 3, 2, 120, 10)\nend)\n\nm:addOverride('xi.actions.spells.white.dia_iii.onSpellCast', function(caster, target, spell)\n    return castEraDia(caster, target, spell, 5, 3, 180, 15)\nend)\n\nm:addOverride('xi.actions.spells.white.diaga.onSpellCast', function(caster, target, spell)\n    return castEraDia(caster, target, spell, 1, 1, 60, 5)\nend)\n\n-----------------------------------\n-- Dark Magic\n-----------------------------------\n\n-- Bio family: Revert attack down values.\n-- Source: https://forum.square-enix.com/ffxi/threads/55263-April.-3-2019-%28JST%29-Version-Update\nlocal function calculateBioPower(caster, tier)\n    local skillLevel = caster:getSkillLevel(xi.skill.DARK_MAGIC)\n\n    if tier == 2 then\n        return utils.clamp(math.ceil(skillLevel / 40), 1, 3)\n    elseif tier == 4 then\n        return utils.clamp(math.floor((skillLevel + 29) / 40), 3, 8)\n    end\n\n    local power = 0\n    if skillLevel > 291 then\n        power = 13 + math.floor((skillLevel - 291) / 27) -- 13 + 1 every 27 skill levels.\n    elseif skillLevel > 246 then\n        power = 9 + math.floor((skillLevel - 246) / 11) -- 9 + 1 every 11 skill levels.\n    else\n        power = 5 + math.floor((skillLevel - 106) / 35) -- 5 + 1 every 35 skill levels.\n    end\n\n    return utils.clamp(power, 5, 17)\nend\n\nlocal function castEraBio(caster, target, spell, tier, duration, attackDown)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n        local power = calculateBioPower(caster, tier)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = duration, origin = caster, tick = 3, subPower = attackDown, tier = tier })\n    end\n\n    return damage\nend\n\nm:addOverride('xi.actions.spells.black.bio.onSpellCast', function(caster, target, spell)\n    return castEraBio(caster, target, spell, 2, 60, 5)\nend)\n\nm:addOverride('xi.actions.spells.black.bio_ii.onSpellCast', function(caster, target, spell)\n    return castEraBio(caster, target, spell, 4, 120, 10)\nend)\n\nm:addOverride('xi.actions.spells.black.bio_iii.onSpellCast', function(caster, target, spell)\n    return castEraBio(caster, target, spell, 6, 180, 15)\nend)\n\n-- Dread Spikes: Revert duration from 3 minutes to 1 minute.\n-- Source: https://forum.square-enix.com/ffxi/threads/48564-Sep-16-2015-%28JST%29-Version-Update\nm:addOverride('xi.effects.dread_spikes.onEffectGain', function(target, effect)\n    super(target, effect)\n    effect:setDuration(60000)\nend)\n\n-- Absorb-STAT: Revert to a fixed 90s duration with a decaying tick.\n-- Source: http://forum.square-enix.com/ffxi/threads/46531-Mar-26-2015-%28JST%29-Version-Update\nlocal absorbStatOverrides =\n{\n    { path = 'xi.actions.spells.black.absorb-str.onSpellCast', boostEffect = xi.effect.STR_BOOST,      downEffect = xi.effect.STR_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-dex.onSpellCast', boostEffect = xi.effect.DEX_BOOST,      downEffect = xi.effect.DEX_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-vit.onSpellCast', boostEffect = xi.effect.VIT_BOOST,      downEffect = xi.effect.VIT_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-agi.onSpellCast', boostEffect = xi.effect.AGI_BOOST,      downEffect = xi.effect.AGI_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-int.onSpellCast', boostEffect = xi.effect.INT_BOOST,      downEffect = xi.effect.INT_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-mnd.onSpellCast', boostEffect = xi.effect.MND_BOOST,      downEffect = xi.effect.MND_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-chr.onSpellCast', boostEffect = xi.effect.CHR_BOOST,      downEffect = xi.effect.CHR_DOWN      },\n    { path = 'xi.actions.spells.black.absorb-acc.onSpellCast', boostEffect = xi.effect.ACCURACY_BOOST, downEffect = xi.effect.ACCURACY_DOWN },\n}\n\nfor _, entry in ipairs(absorbStatOverrides) do\n    m:addOverride(entry.path, function(caster, target, spell)\n        local previousBoost      = caster:getStatusEffect(entry.boostEffect)\n        local previousBoostStart = previousBoost and previousBoost:getStartTime() or nil\n        local previousDown       = target:getStatusEffect(entry.downEffect)\n        local previousDownStart  = previousDown and previousDown:getStartTime() or nil\n\n        local result = super(caster, target, spell)\n\n        local boost = caster:getStatusEffect(entry.boostEffect)\n        if boost and boost:getStartTime() ~= previousBoostStart then\n            boost:setDuration(90000)\n            boost:setTick(10000)\n        end\n\n        local down = target:getStatusEffect(entry.downEffect)\n        if down and down:getStartTime() ~= previousDownStart then\n            down:setDuration(90000)\n            down:setTick(10000)\n        end\n\n        return result\n    end)\nend\n\n-- Drain II: Revert Max HP Boost duration from 3 minutes to 1 minute.\n-- Source: https://forum.square-enix.com/ffxi/threads/48564-Sep-16-2015-%28JST%29-Version-Update\nm:addOverride('xi.actions.spells.black.drain_ii.onSpellCast', function(caster, target, spell)\n    local previousBoost    = caster:getStatusEffect(xi.effect.MAX_HP_BOOST)\n    local previousSubPower = previousBoost and previousBoost:getSubPower() or 0\n\n    local result = super(caster, target, spell)\n\n    local currentBoost = caster:getStatusEffect(xi.effect.MAX_HP_BOOST)\n    if\n        currentBoost and\n        currentBoost:getSubPower() > previousSubPower\n    then\n        currentBoost:setDuration(60000)\n    end\n\n    return result\nend)\n"},["modules/era/lua/combat/magic_burst.lua"]={["Path"]="modules/era/lua/combat/magic_burst.lua",["SHA256"]="43899b2ea0599d4c43581d767d9241ffff0c1c82ca4b0ef33959c4168f552202",["Text"]="-----------------------------------\n-- Pre-SoA Magic Burst Module\n-- Restores the pre-2015 magic burst multiplier: 1.25 + 0.05 per skillchain step.\n-- https://forum.square-enix.com/ffxi/threads/46531\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_magic_burst', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.spells.damage.calculateIfMagicBurst', function(caster, target, spellElement, magicBurstTier)\n    if spellElement <= xi.element.NONE then\n        return 1\n    end\n\n    return 1.25 + 0.05 * utils.clamp(magicBurstTier, 1, 5)\nend)\n"},["modules/phoenix/lua/actions/spells/ninjutsu/damage_ninjutsu.lua"]={["Path"]="modules/phoenix/lua/actions/spells/ninjutsu/damage_ninjutsu.lua",["SHA256"]="4d73edd1271a89723d446cc339e7d34ac5a4a6648df922658f1bea473f31ccbe",["Text"]="-----------------------------------\n-- Module: Damage Ninjutsu Adjustments\n-- Revert the San ninjutsu merits to a per-rank MATT/MACC bonus applied for the cast.\n-- Source: https://forum.square-enix.com/ffxi/threads/55648-July.-8-2019-%28JST%29-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('damage_ninjutsu_adjustments', xi.pre(xi.expansion.ROV))\n\n-- The merit value is the 5 per rank bonus, and the first rank only unlocks the spell.\nlocal meritBySpell =\n{\n    [xi.magic.spell.KATON_SAN ] = xi.merit.KATON_SAN,\n    [xi.magic.spell.HYOTON_SAN] = xi.merit.HYOTON_SAN,\n    [xi.magic.spell.HUTON_SAN ] = xi.merit.HUTON_SAN,\n    [xi.magic.spell.DOTON_SAN ] = xi.merit.DOTON_SAN,\n    [xi.magic.spell.RAITON_SAN] = xi.merit.RAITON_SAN,\n    [xi.magic.spell.SUITON_SAN] = xi.merit.SUITON_SAN,\n}\n\nm:addOverride('xi.spells.damage.calculateMagicBonusDiff', function(caster, target, spellId, skillType, spellElement, bonusMATT)\n    local merit = meritBySpell[spellId]\n\n    if merit then\n        bonusMATT = bonusMATT + math.max(caster:getMerit(merit) - 5, 0)\n    end\n\n    return super(caster, target, spellId, skillType, spellElement, bonusMATT)\nend)\n\n-- Apply magic accuracy merit mod for spell calculations and remove it afterward.\nm:addOverride('xi.spells.damage.useDamageSpell', function(caster, target, spell)\n    local merit = meritBySpell[spell:getID()]\n\n    if not merit then\n        return super(caster, target, spell)\n    end\n\n    local maccBonus = math.max(caster:getMerit(merit) - 5, 0)\n\n    caster:addMod(xi.mod.MACC, maccBonus)\n\n    local castOk, damage = pcall(super, caster, target, spell)\n\n    caster:delMod(xi.mod.MACC, maccBonus)\n\n    if not castOk then\n        error(damage, 0)\n    end\n\n    return damage\nend)\n\nreturn m\n"},["modules/phoenix/lua/globals/spells/damage_spell.lua"]={["Path"]="modules/phoenix/lua/globals/spells/damage_spell.lua",["SHA256"]="2a5b2f06386157ca4bc9d0fc1b45fbfaee9a3d07d7cc88decfdd08c7a3d58c68",["Text"]="-----------------------------------\n-- Module: Damage Spell Adjustments\n-- TODO: Convert to new spell organization once upstream is reworked\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('damage_spell_adjustments')\n\n-----------------------------------\n-- Revert AM2 magic accuracy to pre RoV values, plus merit-based magic burst and magic accuracy.\n-- Source: https://forum.square-enix.com/ffxi/threads/55525-June.-10-2019-%28JST%29-Version-Update\n-----------------------------------\n\n-- These merits carry a value of 1, so getMerit returns the rank count.\nlocal meritBySpell =\n{\n    [xi.magic.spell.FLARE_II  ] = xi.merit.FLARE_II,\n    [xi.magic.spell.FREEZE_II ] = xi.merit.FREEZE_II,\n    [xi.magic.spell.TORNADO_II] = xi.merit.TORNADO_II,\n    [xi.magic.spell.QUAKE_II  ] = xi.merit.QUAKE_II,\n    [xi.magic.spell.BURST_II  ] = xi.merit.BURST_II,\n    [xi.magic.spell.FLOOD_II  ] = xi.merit.FLOOD_II,\n}\n\n-- Revert magic accuracy for BLM AM2 to pre RoV values.\nfor spellId in pairs(meritBySpell) do\n    xi.spells.damage.pTable[spellId][2] = 0 -- column.BONUS_MACC\nend\n\n-- Apply magic accuracy and magic burst merit mods for spell calculations and remove them afterward.\nm:addOverride('xi.spells.damage.useDamageSpell', function(caster, target, spell)\n    local merit     = meritBySpell[spell:getID()]\n    local meritRank = merit and caster:getMerit(merit) or 0\n\n    -- The first rank only unlocks the spell.\n    if meritRank < 2 then\n        return super(caster, target, spell)\n    end\n\n    local maccBonus  = (meritRank - 1) * 5\n    local burstBonus = (meritRank - 1) * 3\n\n    caster:addMod(xi.mod.MACC, maccBonus)\n    caster:addMod(xi.mod.MAGIC_BURST_BONUS_CAPPED, burstBonus)\n\n    local castOk, damage = pcall(super, caster, target, spell)\n\n    caster:delMod(xi.mod.MACC, maccBonus)\n    caster:delMod(xi.mod.MAGIC_BURST_BONUS_CAPPED, burstBonus)\n\n    if not castOk then\n        error(damage, 0)\n    end\n\n    return damage\nend)\n\nreturn m\n"},["modules/phoenix/lua/globals/spells/enfeebling_spell.lua"]={["Path"]="modules/phoenix/lua/globals/spells/enfeebling_spell.lua",["SHA256"]="5422ed7962dc7ec6d568bb152c237c1afb19986a24ac1d1ba2659748e871c3fc",["Text"]="-----------------------------------\n-- Module: Enfeebling Spell Adjustments\n-- Source: https://forum.square-enix.com/ffxi/threads/46531-Mar-26-2015-%28JST%29-Version-Update\n-- TODO: Convert to new spell organization once upstream is reworked\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('enfeebling_spell_adjustments', xi.pre(xi.expansion.SOA))\n\n-- Poison / Poisonga / Poison II: Revert potency formula to pre-2015 values.\n-- Source: https://wiki.ffo.jp/html/833.html\n-- Source: https://forum.square-enix.com/ffxi/threads/46531-Mar-26-2015-%28JST%29-Version-Update\nlocal poisonPotency =\n{\n    [xi.magic.spell.POISON   ] =\n    {\n        { maxSkill = 79,  potency = 1 },\n        { maxSkill = 159, potency = 2 },\n        { maxSkill = 239, potency = 3 },\n        { maxSkill = 999, potency = 4 },\n    },\n\n    [xi.magic.spell.POISONGA ] =\n    {\n        { maxSkill = 79,  potency = 1 },\n        { maxSkill = 159, potency = 2 },\n        { maxSkill = 239, potency = 3 },\n        { maxSkill = 999, potency = 4 },\n    },\n\n    [xi.magic.spell.POISON_II] =\n    {\n        { maxSkill = 124, potency = 4  },\n        { maxSkill = 149, potency = 5  },\n        { maxSkill = 174, potency = 6  },\n        { maxSkill = 199, potency = 7  },\n        { maxSkill = 224, potency = 8  },\n        { maxSkill = 249, potency = 9  },\n        { maxSkill = 999, potency = 10 },\n    },\n}\n\n-- Blind / Blind II: Revert post-2015 potency formula.\n-- Poison / Poison II / Poisonga: Revert post-2015 potency formula\n-- Dokumori: Ichi: Revert slip damage to 2 HP per tick.\n-- Source: https://forum.square-enix.com/ffxi/threads/46531-Mar-26-2015-%28JST%29-Version-Update\n-- Source: https://wiki.ffo.jp/html/3596.html\nm:addOverride('xi.spells.enfeebling.calculatePotency', function(caster, target, spellId, spellEffect, skillType, statUsed)\n    if spellId == xi.magic.spell.DOKUMORI_ICHI then\n        return 2\n    end\n\n    local potency\n\n    if\n        spellId == xi.magic.spell.BLIND or\n        spellId == xi.magic.spell.BLIND_II\n    then\n        local statDiff = caster:getStat(statUsed) - target:getStat(xi.mod.MND)\n        local offset   = spellId == xi.magic.spell.BLIND_II and 100 or 60\n        potency = math.max(math.floor((statDiff + offset) / 4), 0)\n\n    elseif poisonPotency[spellId] then\n        local skillLevel = caster:getSkillLevel(skillType)\n\n        for _, entry in ipairs(poisonPotency[spellId]) do\n            if skillLevel <= entry.maxSkill then\n                potency = entry.potency\n                break\n            end\n        end\n\n    else\n        return super(caster, target, spellId, spellEffect, skillType, statUsed)\n    end\n\n    if\n        caster:hasStatusEffect(xi.effect.SABOTEUR) and\n        skillType == xi.skill.ENFEEBLING_MAGIC\n    then\n        if target:isNM() then\n            potency = math.floor(potency * (1.3 + caster:getMod(xi.mod.ENHANCES_SABOTEUR)))\n        else\n            potency = math.floor(potency * (2 + caster:getMod(xi.mod.ENHANCES_SABOTEUR)))\n        end\n    end\n\n    -- General Enfeebling potency modifier.\n    return math.floor(potency * (1 + caster:getMod(xi.mod.ENF_MAG_POTENCY) / 100))\nend)\n\n-- Blind / Blind II: Revert fixed 180s duration to variable duration.\n-- Paralyze / Paralyze II / Silence: Revert fixed 120s duration to variable duration.\n-- Poison / Poisonga: Revert base duration to 30s.\nm:addOverride('xi.spells.enfeebling.calculateDuration', function(caster, target, spellId, spellEffect, skillType)\n    local duration = 0\n\n    if\n        spellId == xi.magic.spell.BLIND or\n        spellId == xi.magic.spell.BLIND_II\n    then\n        duration = math.randomInt(80, 300)\n    elseif\n        spellId == xi.magic.spell.PARALYZE or\n        spellId == xi.magic.spell.PARALYZE_II\n    then\n        duration = math.randomInt(30, 120)\n    elseif spellId == xi.magic.spell.SILENCE then\n        -- Distribution is likely not uniform. Needs more research.\n        duration = math.randomInt(30, 120)\n    elseif\n        spellId == xi.magic.spell.POISON or\n        spellId == xi.magic.spell.POISONGA\n    then\n        duration = 30\n    else\n        return super(caster, target, spellId, spellEffect, skillType)\n    end\n\n    if skillType == xi.skill.ENFEEBLING_MAGIC then\n        if caster:hasStatusEffect(xi.effect.SABOTEUR) then\n            if target:isNM() then\n                duration = duration * 1.25\n            else\n                duration = duration * 2\n            end\n        end\n\n        if caster:getMainJob() == xi.job.RDM then\n            duration = duration + caster:getMerit(xi.merit.ENFEEBLING_MAGIC_DURATION)\n            duration = duration + caster:getJobPointLevel(xi.jp.ENFEEBLE_DURATION)\n\n            if caster:hasStatusEffect(xi.effect.STYMIE) then\n                duration = duration + caster:getJobPointLevel(xi.jp.STYMIE_EFFECT)\n            end\n        end\n\n        duration = math.floor(duration * (1 + caster:getMod(xi.mod.ENF_MAG_DURATION) / 100))\n    end\n\n    return math.floor(duration)\nend)\n\n-----------------------------------\n-- Merits: Slow II / Paralyze II / Blind II potency and magic accuracy.\n-- Source: https://forum.square-enix.com/ffxi/threads/55751-August.-6-2019-%28JST%29-Version-Update\n-----------------------------------\nlocal merits = Module:new('enfeebling_merit_adjustments', xi.pre(xi.expansion.ROV))\n\n-- Merit value is 1, so getMerit is the rank count; rank one only unlocks the spell.\n-- ranksInBase: ranks core's potency already carries - five for the 2019 formulas, one for Blind II, reverted above to its pre-2015 formula.\nlocal meritBySpell =\n{\n    [xi.magic.spell.SLOW_II    ] = { merit = xi.merit.SLOW_II,     potency = 100, ranksInBase = 5, magicAccuracy = 2 },\n    [xi.magic.spell.PARALYZE_II] = { merit = xi.merit.PARALYZE_II, potency = 1,   ranksInBase = 5, magicAccuracy = 2 },\n    [xi.magic.spell.BLIND_II   ] = { merit = xi.merit.BLIND_II,    potency = 1,   ranksInBase = 1, magicAccuracy = 2 },\n}\n\nmerits:addOverride('xi.spells.enfeebling.calculatePotency', function(caster, target, spellId, spellEffect, skillType, statUsed)\n    local potency = super(caster, target, spellId, spellEffect, skillType, statUsed)\n    local entry   = meritBySpell[spellId]\n\n    if entry then\n        local meritRank = math.max(caster:getMerit(entry.merit), 1)\n        potency = potency + (meritRank - entry.ranksInBase) * entry.potency\n    end\n\n    return potency\nend)\n\n-- Apply magic accuracy merit mod for spell calculations and remove it afterward.\nmerits:addOverride('xi.spells.enfeebling.useEnfeeblingSpell', function(caster, target, spell)\n    local entry     = meritBySpell[spell:getID()]\n    local meritRank = entry and caster:getMerit(entry.merit) or 0\n\n    if meritRank < 2 then\n        return super(caster, target, spell)\n    end\n\n    local maccBonus = (meritRank - 1) * entry.magicAccuracy\n\n    caster:addMod(xi.mod.MACC, maccBonus)\n\n    local castOk, spellEffect = pcall(super, caster, target, spell)\n\n    caster:delMod(xi.mod.MACC, maccBonus)\n\n    if not castOk then\n        error(spellEffect, 0)\n    end\n\n    return spellEffect\nend)\n\nreturn m\n"},["modules/phoenix/lua/globals/spells/enhancing_spell.lua"]={["Path"]="modules/phoenix/lua/globals/spells/enhancing_spell.lua",["SHA256"]="ab94f36e3d9e415c9c39b75f0092b87872bf6634309ed0a771da2b07040b34a7",["Text"]="-----------------------------------\n-- Module: Enhancing Spell Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('enhancing_spell_adjustments')\n\nlocal column =\n{\n    EFFECT_LEVEL     = 3,\n    EFFECT_POWER     = 4,\n    EFFECT_DURATION  = 5,\n    EFFECT_COMPOSURE = 6,\n}\n\n-- Protect / Shell: Revert power caps.\n-- Source: https://forum.square-enix.com/ffxi/threads/55360-May.-10-2019-%28JST%29-Version-Update?p=615387&viewfull=1#post615387\nlocal eraBasePower =\n{\n    [xi.magic.spell.PROTECT      ] =   10,\n    [xi.magic.spell.PROTECT_II   ] =   25,\n    [xi.magic.spell.PROTECT_III  ] =   40,\n    [xi.magic.spell.PROTECT_IV   ] =   55,\n    [xi.magic.spell.PROTECT_V    ] =   60,\n    [xi.magic.spell.PROTECTRA    ] =   10,\n    [xi.magic.spell.PROTECTRA_II ] =   25,\n    [xi.magic.spell.PROTECTRA_III] =   40,\n    [xi.magic.spell.PROTECTRA_IV ] =   55,\n    [xi.magic.spell.PROTECTRA_V  ] =   60,\n    [xi.magic.spell.SHELL        ] =  937,\n    [xi.magic.spell.SHELL_II     ] = 1406,\n    [xi.magic.spell.SHELL_III    ] = 1875,\n    [xi.magic.spell.SHELL_IV     ] = 2187,\n    [xi.magic.spell.SHELL_V      ] = 2421,\n    [xi.magic.spell.SHELLRA      ] =  937,\n    [xi.magic.spell.SHELLRA_II   ] = 1406,\n    [xi.magic.spell.SHELLRA_III  ] = 1875,\n    [xi.magic.spell.SHELLRA_IV   ] = 2187,\n    [xi.magic.spell.SHELLRA_V    ] = 2421,\n}\n\nfor spellId, basePower in pairs(eraBasePower) do\n    xi.spells.enhancing.spellPTable[spellId][column.EFFECT_POWER] = basePower\nend\n\n-- Deodorize / Sneak / Invisible: Revert base duration to a random 30s-300s.\n-- Bar-status: Revert the flat 480s base to a skill scaled duration.\n-- Source: https://forum.square-enix.com/ffxi/threads/32909-April-30-2013-%28JST%29-Version-Update\nm:addOverride('xi.spells.enhancing.calculateEnhancingDuration', function(caster, target, spell, spellId, spellGroup, spellEffect)\n    -- Swap the base duration in for the cast; everything past it mirrors core.\n    if spellEffect >= xi.effect.BARFIRE and spellEffect <= xi.effect.BARWATER then\n        local barRow         = xi.spells.enhancing.spellPTable[spellId]\n        local coreDuration   = barRow[column.EFFECT_DURATION]\n        local enhancingSkill = caster:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n\n        barRow[column.EFFECT_DURATION] = 150 + math.max(enhancingSkill - 180, 0) * 0.8\n\n        local castOk, duration = pcall(super, caster, target, spell, spellId, spellGroup, spellEffect)\n\n        barRow[column.EFFECT_DURATION] = coreDuration\n\n        if not castOk then\n            error(duration, 0)\n        end\n\n        return duration\n    end\n\n    if\n        spellEffect ~= xi.effect.DEODORIZE and\n        spellEffect ~= xi.effect.INVISIBLE and\n        spellEffect ~= xi.effect.SNEAK\n    then\n        return super(caster, target, spell, spellId, spellGroup, spellEffect)\n    end\n\n    local spellRow     = xi.spells.enhancing.spellPTable[spellId]\n    local spellLevel   = spellRow[column.EFFECT_LEVEL]\n    local useComposure = spellRow[column.EFFECT_COMPOSURE]\n    local targetLevel  = target:getMainLvl()\n\n    -- Reverted base duration.\n    local duration = math.randomInt(30, 300)\n\n    -- Gear durations (e.g. Skulker's Cape).\n    if spellEffect == xi.effect.INVISIBLE then\n        duration = duration + target:getMod(xi.mod.INVISIBLE_DURATION)\n    elseif spellEffect == xi.effect.SNEAK then\n        duration = duration + target:getMod(xi.mod.SNEAK_DURATION)\n    end\n\n    -- Composure.\n    if\n        useComposure and\n        caster:hasStatusEffect(xi.effect.COMPOSURE) and\n        caster:getID() == target:getID()\n    then\n        duration = duration * 3\n    end\n\n    -- Level penalty to duration.\n    if targetLevel < spellLevel then\n        duration = duration * targetLevel / spellLevel\n    end\n\n    return duration\nend)\n\n-----------------------------------\n-- Merits: Protectra V / Shellra V (power), Phalanx II (power and duration).\n-- Source: https://forum.square-enix.com/ffxi/threads/55360-May.-10-2019-%28JST%29-Version-Update?p=615387&viewfull=1#post615387\n-- Source: https://forum.square-enix.com/ffxi/threads/55751-August.-6-2019-%28JST%29-Version-Update\n-----------------------------------\n\n-- ranksInBase: merit ranks the value out of core already carries.\n-- Phalanx II keeps its 2019 base (skill / 25 + 16 and 240s)\nlocal meritBonusBySpell =\n{\n    [xi.magic.spell.PROTECTRA_V] = { merit = xi.merit.PROTECTRA_V, valuePerRank = 5, ranksInBase = 1, power = 2  },\n    [xi.magic.spell.SHELLRA_V  ] = { merit = xi.merit.SHELLRA_V,   valuePerRank = 2, ranksInBase = 1, power = 78 },\n    [xi.magic.spell.PHALANX_II ] = { merit = xi.merit.PHALANX_II,  valuePerRank = 3, ranksInBase = 5, power = 3, duration = 30 },\n}\n\nm:addOverride('xi.spells.enhancing.calculateEnhancingFinalPower', function(caster, target, spell, basePower, spellGroup, tier, spellEffect)\n    local finalPower = super(caster, target, spell, basePower, spellGroup, tier, spellEffect)\n    local entry      = meritBonusBySpell[spell:getID()]\n\n    if entry then\n        local meritRank = math.max(caster:getMerit(entry.merit) / entry.valuePerRank, 1)\n        finalPower = finalPower + (meritRank - entry.ranksInBase) * entry.power\n    end\n\n    return finalPower\nend)\n\nm:addOverride('xi.spells.enhancing.calculateEnhancingDuration', function(caster, target, spell, spellId, spellGroup, spellEffect)\n    local duration = super(caster, target, spell, spellId, spellGroup, spellEffect)\n    local entry    = meritBonusBySpell[spellId]\n\n    if entry and entry.duration then\n        local meritRank = math.max(caster:getMerit(entry.merit) / entry.valuePerRank, 1)\n        duration = duration + (meritRank - entry.ranksInBase) * entry.duration\n    end\n\n    return duration\nend)\n\nreturn m\n"},["scripts/actions/spells/black/absorb-acc.lua"]={["Path"]="scripts/actions/spells/black/absorb-acc.lua",["SHA256"]="10b1156c9adcbb29808f448dc702a9fa37c4a1f2e4ef027086979d4dcc5b90a8",["Text"]="-----------------------------------\n-- Spell: Absorb-ACC\n-- Steals an enemy's accuracy.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-agi.lua"]={["Path"]="scripts/actions/spells/black/absorb-agi.lua",["SHA256"]="749693cbdb7059b758f98401fd3a70462ac6f3b6c4e853e5e3cd71ce1c1d0f24",["Text"]="-----------------------------------\n-- Spell: Absorb-AGI\n-- Steals an enemy's agility.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-attri.lua"]={["Path"]="scripts/actions/spells/black/absorb-attri.lua",["SHA256"]="1e81e54733cbfbd88faf992d23ffc5e0f3ab9b5cc3a51f27b2822b8d73ace413",["Text"]="-----------------------------------\n-- Spell: Absorb-Attri\n-- Steals an enemy's beneficial status effects.\n-- NOTE: Nether Void allows for two beneficial status effects to be absorbed.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbAttriSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-chr.lua"]={["Path"]="scripts/actions/spells/black/absorb-chr.lua",["SHA256"]="3101452f1a13d5976805fd47c1c61eeced77d9fb33d8a8387178bc48a2f30c6f",["Text"]="-----------------------------------\n-- Spell: Absorb-CHR\n-- Steals an enemy's Charisma.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-dex.lua"]={["Path"]="scripts/actions/spells/black/absorb-dex.lua",["SHA256"]="e2de89c404f1cb24a9c955dbd36b1f4164dbbeb23edba4372045fda1cd0e8159",["Text"]="-----------------------------------\n-- Spell: Absorb-DEX\n-- Steals an enemy's dexterity.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-int.lua"]={["Path"]="scripts/actions/spells/black/absorb-int.lua",["SHA256"]="e9d5d667dc594c276ef02876d2684b5399086f5c80149641b258bc37845c82eb",["Text"]="-----------------------------------\n-- Spell: Absorb-INT\n-- Steals an enemy's intelligence.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-mnd.lua"]={["Path"]="scripts/actions/spells/black/absorb-mnd.lua",["SHA256"]="709a300e4ef920110c4d67c339ada47f82f6e58919bdc5178d0b3ba20b09573a",["Text"]="-----------------------------------\n-- Spell: Absorb-MND\n-- Steals an enemy's mind.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-str.lua"]={["Path"]="scripts/actions/spells/black/absorb-str.lua",["SHA256"]="4c8ee27d54055d09ac330f7953dd6ab3b4835d21a47e9bfc1b75c94ddd1435c9",["Text"]="-----------------------------------\n-- Spell: Absorb-STR\n-- Steals an enemy's strength.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-tp.lua"]={["Path"]="scripts/actions/spells/black/absorb-tp.lua",["SHA256"]="ab44d7fd3375405b316a5894cb3ca097f0ee55a5ece4a5bcc52ed3875b23ec79",["Text"]="-----------------------------------\n-- Spell: Absorb-TP\n-- Steals an enemy's TP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbTPSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/absorb-vit.lua"]={["Path"]="scripts/actions/spells/black/absorb-vit.lua",["SHA256"]="c9d7381bb548fdc023da4fdb0614e9bdf116aec18a11595d369d71b15dd28c8f",["Text"]="-----------------------------------\n-- Spell: Absorb-VIT\n-- Steals an enemy's vitality.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doAbsorbStatSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/aera.lua"]={["Path"]="scripts/actions/spells/black/aera.lua",["SHA256"]="1ccb02c1ae09d5bf1edee8c2075d6e00392b8078a2c17930c166c3fe8f673dda",["Text"]="-----------------------------------\n-- Spell: Aera\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/aera_ii.lua"]={["Path"]="scripts/actions/spells/black/aera_ii.lua",["SHA256"]="d84a8be2ab28336cd25025e7e35c0b52c2b8f67de40c1239752e5bacce2adfc4",["Text"]="-----------------------------------\n-- Spell: Aera II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/aero.lua"]={["Path"]="scripts/actions/spells/black/aero.lua",["SHA256"]="391708b880d18fc57886c55454f49a5a724e2042dfb67a83fbc4de5040d52abc",["Text"]="-----------------------------------\n-- Spell: Aero\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, targ