b63fa4ca42bea76c0791f5e5ecf517bc0117483da7",["Text"]="-----------------------------------\n-- Spell: Aeroja\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/anemohelix.lua"]={["Path"]="scripts/actions/spells/black/anemohelix.lua",["SHA256"]="634d3959c4de907a9aef92bbc12437ba58ebdb7a447330102984571da7902292",["Text"]="-----------------------------------\n-- Spell: Anemohelix\n-- Deals wind damage that gradually reduces target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/anemohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/anemohelix_ii.lua",["SHA256"]="fb41cfd78572c29fa1e8275994fb82a7bd2c20e2514cca7a2a5edb27599ae7f1",["Text"]="-----------------------------------\n-- Spell: Anemohelix II\n-- Deals wind damage that gradually reduces target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"}};
